/* ==========================================================================
   VELOCE — منطق فروشگاه
   1. داده محصولات
   2. توابع کمکی
   3. رندر محصولات + فیلتر + مرتب‌سازی
   4. سبد خرید
   5. نمای سریع (Modal)
   6. هدر، منوی موبایل، اسکرول
   7. ریویل با IntersectionObserver + شمارنده آمار
   8. خبرنامه + Toast + بازگشت به بالا
   ========================================================================== */

(function () {
  'use strict';

  /* -------------------- 1. داده محصولات -------------------- */

  // عکس‌های واقعی محصولات (Base64، جاسازی‌شده تا همیشه بدون وابستگی به فایل جانبی نمایش داده شوند)
  const PRODUCT_PHOTOS = {
    nikeBlack: 'data:image/jpeg;base64,',
    airmaxRed: 'data:image/jpeg;base64,',
    onCloud: 'data:image/jpeg;base64,',
    nb990: 'data:image/jpeg;base64,',
    copaRed: 'data:image/jpeg;base64,',
    nb9060Black: 'data:image/jpeg;base64,',
    asicsGel: 'data:image/jpeg;base64,',
    nb9060White: 'data:image/jpeg;base64,',
    onCloudWhite: 'data:image/jpeg;base64,',
    samba: 'data:image/jpeg;base64,',
    blackClean: 'data:image/jpeg;base64,',
    group3: 'data:image/jpeg;base64,',
    blackRedChunky: 'data:image/jpeg;base64,',
  };

  const PRODUCTS = [
    { id: 1,  name: 'ایرگلایت رانر',       category: 'running',    price: 2450000, oldPrice: null,    color: '#ff4d3d', badge: 'پرفروش', date: '2024-01-10', photo: 'nikeBlack' },
    { id: 2,  name: 'استریت‌واک کژوال',     category: 'casual',     price: 1890000, oldPrice: 2190000, color: '#3d6bff', badge: 'تخفیف',  date: '2023-11-02', photo: 'samba' },
    { id: 3,  name: 'دانک‌پرو بسکتبال',      category: 'basketball', price: 3190000, oldPrice: null,    color: '#8a3dff', badge: null,     date: '2024-02-20', photo: 'blackRedChunky' },
    { id: 4,  name: 'ایزی‌فلوت اسلیپ‌آن',    category: 'slipon',     price: 1450000, oldPrice: null,    color: '#0fb37d', badge: 'جدید',   date: '2024-03-01', photo: 'blackClean' },
    { id: 5,  name: 'ولوسیتی X۲ رانینگ',    category: 'running',    price: 2790000, oldPrice: 3090000, color: '#ff4d3d', badge: 'تخفیف',  date: '2023-09-14', photo: 'airmaxRed' },
    { id: 6,  name: 'اربن‌دیز کژوال',        category: 'casual',     price: 1690000, oldPrice: null,    color: '#3d6bff', badge: null,     date: '2023-12-19', photo: 'group3' },
    { id: 7,  name: 'اسکای‌جامپ بسکتبال',    category: 'basketball', price: 3450000, oldPrice: null,    color: '#8a3dff', badge: 'جدید',   date: '2024-03-18', photo: 'onCloud' },
    { id: 8,  name: 'کامفی‌گلاید اسلیپ‌آن',  category: 'slipon',     price: 1290000, oldPrice: null,    color: '#0fb37d', badge: null,     date: '2023-08-05', photo: 'nikeBlack' },
    { id: 9,  name: 'مارتون رانینگ پرو',     category: 'running',    price: 3090000, oldPrice: null,    color: '#ff4d3d', badge: null,     date: '2024-01-28', photo: 'onCloud' },
    { id: 10, name: 'ریترو کژوال کلاسیک',    category: 'casual',     price: 2090000, oldPrice: 2390000, color: '#3d6bff', badge: 'تخفیف',  date: '2023-10-11', photo: 'blackClean' },
    { id: 11, name: 'کورت‌کینگ بسکتبال',     category: 'basketball', price: 2990000, oldPrice: null,    color: '#8a3dff', badge: 'پرفروش', date: '2023-07-22', photo: 'samba' },
    { id: 12, name: 'لایت‌استپ اسلیپ‌آن',    category: 'slipon',     price: 1590000, oldPrice: null,    color: '#0fb37d', badge: 'جدید',   date: '2024-03-25', photo: 'group3' },
    { id: 13, name: 'فلای‌مود رانینگ',       category: 'running',    price: 2650000, oldPrice: 2950000, color: '#ff4d3d', badge: 'تخفیف',  date: '2024-02-05', photo: 'airmaxRed' },
    { id: 14, name: 'پالس‌رانر اسپرت',       category: 'running',    price: 2990000, oldPrice: null,    color: '#ff4d3d', badge: null,     date: '2023-12-30', photo: 'nikeBlack' },
    { id: 15, name: 'دیلی‌واک کژوال',        category: 'casual',     price: 1790000, oldPrice: null,    color: '#3d6bff', badge: 'جدید',   date: '2024-03-08', photo: 'samba' },
    { id: 16, name: 'نئوکلاسیک کژوال',       category: 'casual',     price: 2190000, oldPrice: null,    color: '#3d6bff', badge: null,     date: '2023-09-27', photo: 'blackClean' },
    { id: 17, name: 'پاورجامپ بسکتبال',      category: 'basketball', price: 3290000, oldPrice: 3590000, color: '#8a3dff', badge: 'تخفیف',  date: '2024-01-15', photo: 'blackRedChunky' },
    { id: 18, name: 'الیت‌کورت بسکتبال',     category: 'basketball', price: 3650000, oldPrice: null,    color: '#8a3dff', badge: 'جدید',   date: '2024-03-21', photo: 'onCloud' },
    { id: 19, name: 'کژوال‌فلکس اسلیپ‌آن',   category: 'slipon',     price: 1390000, oldPrice: null,    color: '#0fb37d', badge: null,     date: '2023-11-19', photo: 'group3' },
    { id: 20, name: 'ایزی‌دی اسلیپ‌آن',      category: 'slipon',     price: 1690000, oldPrice: 1890000, color: '#0fb37d', badge: 'تخفیف',  date: '2024-02-27', photo: 'samba' },
    { id: 21, name: 'کوپا استرایکر فوتبال',   category: 'football',   price: 2190000, oldPrice: null,    color: '#ff2d55', badge: 'پرفروش', date: '2024-03-30', photo: 'copaRed' },
    { id: 22, name: 'فیلدمستر کرامپون',       category: 'football',   price: 1990000, oldPrice: 2290000, color: '#ff2d55', badge: 'تخفیف',  date: '2024-01-05', photo: 'copaRed' },
    { id: 23, name: 'پرو‌پیچ فوتبال کلیت',     category: 'football',   price: 2450000, oldPrice: null,    color: '#ff2d55', badge: 'جدید',   date: '2024-03-27', photo: 'copaRed' },
    { id: 24, name: 'استادیوم‌ایکس فوتبال',    category: 'football',   price: 2690000, oldPrice: null,    color: '#ff2d55', badge: null,     date: '2023-10-22', photo: 'copaRed' },
    { id: 25, name: 'گل‌زن اکسترا فوتبال',     category: 'football',   price: 2090000, oldPrice: null,    color: '#ff2d55', badge: null,     date: '2023-08-14', photo: 'copaRed' },
    { id: 26, name: 'نیوبالانس ۹۹۰ کلاسیک',   category: 'running',    price: 4290000, oldPrice: null,    color: '#6b7280', badge: 'پرفروش', date: '2024-02-11', photo: 'nb990' },
    { id: 27, name: 'نیوبالانس ۹۰۶۰ کربن',    category: 'casual',     price: 3990000, oldPrice: 4390000, color: '#6b7280', badge: 'تخفیف',  date: '2023-12-02', photo: 'nb9060Black' },
    { id: 28, name: 'نیوبالانس ۹۰۶۰ کرمی',    category: 'casual',     price: 3990000, oldPrice: null,    color: '#6b7280', badge: 'جدید',   date: '2024-03-14', photo: 'nb9060White' },
    { id: 29, name: 'اسیکس جل کوانتوم',       category: 'running',    price: 3690000, oldPrice: null,    color: '#3d6bff', badge: null,     date: '2023-11-25', photo: 'asicsGel' },
    { id: 30, name: 'آن‌کلود ترمو‌فیز',        category: 'running',    price: 4590000, oldPrice: null,    color: '#14171f', badge: 'جدید',   date: '2024-03-05', photo: 'onCloudWhite' },
  ];

  const CATEGORY_LABELS = {
    running: 'رانینگ',
    casual: 'کژوال',
    basketball: 'بسکتبال',
    football: 'فوتبال',
    slipon: 'اسلیپ‌آن',
  };

  const SIZES = [38, 39, 40, 41, 42, 43, 44];

  /* -------------------- 2. توابع کمکی -------------------- */
  const $ = (sel, ctx = document) => ctx.querySelector(sel);
  const $$ = (sel, ctx = document) => Array.from(ctx.querySelectorAll(sel));

  function formatToman(amount) {
    return amount.toLocaleString('fa-IR') + ' تومان';
  }

  // تنظیمات ظاهری هر دسته: ارتفاع یقه (بلندی مچ)، وجود بند، وجود کش کناری (اسلیپ‌آن)
  const SHOE_CONFIG = {
    running:    { collarTop: 40, laces: true,  gore: false },
    casual:     { collarTop: 46, laces: true,  gore: false },
    basketball: { collarTop: 14, laces: true,  gore: false },
    football:   { collarTop: 44, laces: true,  gore: false },
    slipon:     { collarTop: 50, laces: false, gore: true  },
  };

  // ساخت یک ایلوستریشن SVG تمیز از کفش، متناسب با دسته‌بندی و رنگ محصول
  function buildShoeSVG(category, color, uid) {
    const cfg = SHOE_CONFIG[category] || SHOE_CONFIG.casual;
    const gradId = 'shoeGrad-' + uid;

    const laces = cfg.laces ? `
      <g stroke="rgba(20,23,31,.35)" stroke-width="2.4" stroke-linecap="round">
        <line x1="96" y1="74" x2="118" y2="49"/>
        <line x1="105" y1="80" x2="127" y2="55"/>
        <line x1="114" y1="86" x2="136" y2="61"/>
        <line x1="123" y1="92" x2="145" y2="67"/>
      </g>` : '';

    const gore = cfg.gore ? `
      <path d="M128 80 Q144 60 160 80 Q144 92 128 80 Z" fill="rgba(20,23,31,.16)"/>` : '';

    return `
      <svg viewBox="0 0 220 130" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="ایلوستریشن کفش">
        <defs>
          <linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="${color}" stop-opacity=".88"/>
            <stop offset="1" stop-color="${color}"/>
          </linearGradient>
        </defs>

        <ellipse cx="108" cy="121" rx="84" ry="7" fill="rgba(20,23,31,.10)"/>

        <path d="M172 ${cfg.collarTop} C183 ${cfg.collarTop} 193 ${cfg.collarTop + 8} 197 ${cfg.collarTop + 18} L197 60 L172 60 Z" fill="url(#${gradId})"/>

        <path d="M20 88 C16 68 30 50 52 44 L88 34 C104 29 122 30 136 37 L172 54 C186 61 195 72 196 86 L196 92 L20 92 Z" fill="url(#${gradId})"/>

        <ellipse cx="42" cy="66" rx="16" ry="12" fill="#ffffff" opacity=".16"/>

        ${laces}
        ${gore}

        <path d="M14 100 C10 92 16 86 26 85 L165 82 C185 82 200 90 206 102 C209 108 205 114 197 115 L22 115 C15 115 12 106 14 100 Z" fill="#1b1e26"/>

        <path d="M18 92 C30 86 60 84 100 84 L165 84 C180 84 194 90 200 98" fill="none" stroke="${color}" stroke-width="5" stroke-linecap="round" opacity=".9"/>
      </svg>`;
  }

  // تصویر نمایشی محصول: اگر عکس واقعی موجود باشد از آن استفاده می‌شود، در غیر این صورت از ایلوستریشن SVG
  function productVisual(product, uid) {
    const photo = PRODUCT_PHOTOS[product.photo];
    if (photo) {
      return `<img src="${photo}" alt="${product.name}" loading="lazy" style="--tag-color:${product.color}">`;
    }
    return buildShoeSVG(product.category, product.color, uid);
  }

  /* -------------------- 3. رندر محصولات -------------------- */
  const productGrid = $('#productGrid');
  const emptyState = $('#emptyState');
  const categoryChips = $('#categoryChips');
  const sortSelect = $('#sortSelect');
  const sortSelectBtn = $('#sortSelectBtn');
  const sortSelectList = $('#sortSelectList');
  const sortSelectLabel = $('#sortSelectLabel');

  function openSortDropdown() {
    sortSelect.classList.add('open');
    sortSelectBtn.setAttribute('aria-expanded', 'true');
    sortSelectList.hidden = false;
  }
  function closeSortDropdown() {
    sortSelect.classList.remove('open');
    sortSelectBtn.setAttribute('aria-expanded', 'false');
    sortSelectList.hidden = true;
  }

  sortSelectBtn.addEventListener('click', () => {
    sortSelect.classList.contains('open') ? closeSortDropdown() : openSortDropdown();
  });

  sortSelectList.addEventListener('click', (e) => {
    const item = e.target.closest('li');
    if (!item) return;
    $$('li', sortSelectList).forEach(li => li.setAttribute('aria-selected', 'false'));
    item.setAttribute('aria-selected', 'true');
    sortSelectLabel.textContent = item.textContent;
    activeSort = item.dataset.value;
    closeSortDropdown();
    renderProducts();
  });

  document.addEventListener('click', (e) => {
    if (!sortSelect.contains(e.target)) closeSortDropdown();
  });

  let activeCategory = 'all';
  let activeSort = 'default';

  function getFilteredProducts() {
    let list = activeCategory === 'all'
      ? [...PRODUCTS]
      : PRODUCTS.filter(p => p.category === activeCategory);

    switch (activeSort) {
      case 'cheap':
        list.sort((a, b) => a.price - b.price);
        break;
      case 'expensive':
        list.sort((a, b) => b.price - a.price);
        break;
      case 'new':
        list.sort((a, b) => new Date(b.date) - new Date(a.date));
        break;
      default:
        break;
    }
    return list;
  }

  function renderProducts() {
    const list = getFilteredProducts();
    productGrid.innerHTML = '';

    if (list.length === 0) {
      emptyState.hidden = false;
    } else {
      emptyState.hidden = true;
    }

    list.forEach((product, index) => {
      const card = document.createElement('article');
      card.className = 'product-card';
      card.style.setProperty('--tag-color', product.color);
      card.style.animationDelay = `${index * 60}ms`;

      const discountBadge = product.oldPrice
        ? `<span class="badge">${product.badge || 'تخفیف'}</span>`
        : (product.badge ? `<span class="badge">${product.badge}</span>` : '<span></span>');

      card.innerHTML = `
        <div class="card-trail"></div>
        <div class="card-top">
          ${discountBadge}
          <button class="icon-btn wish-btn" aria-label="افزودن به علاقه‌مندی‌ها" data-wish="${product.id}">
            <svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 20s-7-4.3-9.5-8.8C.8 8 2.4 4.5 6 4.5c2.2 0 3.7 1.2 6 3.7 2.3-2.5 3.8-3.7 6-3.7 3.6 0 5.2 3.5 3.5 6.7C19 15.7 12 20 12 20Z"/></svg>
          </button>
        </div>
        <div class="card-media" data-quickview="${product.id}">
          ${productVisual(product, 'card-' + product.id)}
        </div>
        <div class="card-body">
          <span class="card-cat">${CATEGORY_LABELS[product.category]}</span>
          <h3 class="card-name">${product.name}</h3>
          <div class="card-bottom">
            <span class="card-price price-mono">
              ${formatToman(product.price)}
              ${product.oldPrice ? `<span class="old">${formatToman(product.oldPrice)}</span>` : ''}
            </span>
            <button class="add-btn" data-add="${product.id}" aria-label="افزودن به سبد خرید">
              <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>
            </button>
          </div>
        </div>
      `;
      productGrid.appendChild(card);
    });
  }

  categoryChips.addEventListener('click', (e) => {
    const chip = e.target.closest('.chip');
    if (!chip) return;
    $$('.chip', categoryChips).forEach(c => { c.classList.remove('active'); c.setAttribute('aria-selected', 'false'); });
    chip.classList.add('active');
    chip.setAttribute('aria-selected', 'true');
    activeCategory = chip.dataset.cat;
    renderProducts();
  });

  productGrid.addEventListener('click', (e) => {
    const wishBtn = e.target.closest('[data-wish]');
    if (wishBtn) { wishBtn.classList.toggle('active'); return; }

    const addBtn = e.target.closest('[data-add]');
    if (addBtn) {
      const id = Number(addBtn.dataset.add);
      addToCart(id, SIZES[2]);
      showToast('به سبد خرید اضافه شد ✓');
      return;
    }

    const mediaBtn = e.target.closest('[data-quickview]');
    if (mediaBtn) {
      openQuickView(Number(mediaBtn.dataset.quickview));
    }
  });

  /* -------------------- 4. سبد خرید -------------------- */
  let cart = []; // { id, size, qty }

  const cartDrawer = $('#cartDrawer');
  const cartItemsEl = $('#cartItems');
  const cartCountEl = $('#cartCount');
  const cartTotalEl = $('#cartTotal');
  const cartBtn = $('#cartBtn');
  const closeCartBtn = $('#closeCart');
  const overlay = $('#overlay');
  const cartEmptyBtn = $('#cartEmptyBtn');

  function addToCart(id, size) {
    const existing = cart.find(item => item.id === id && item.size === size);
    if (existing) {
      existing.qty += 1;
    } else {
      cart.push({ id, size, qty: 1 });
    }
    renderCart();
    bumpCartCount();
  }

  function changeQty(id, size, delta) {
    const item = cart.find(i => i.id === id && i.size === size);
    if (!item) return;
    item.qty += delta;
    if (item.qty <= 0) {
      cart = cart.filter(i => !(i.id === id && i.size === size));
    }
    renderCart();
  }

  function removeFromCart(id, size) {
    cart = cart.filter(i => !(i.id === id && i.size === size));
    renderCart();
  }

  function bumpCartCount() {
    cartCountEl.classList.remove('bump');
    void cartCountEl.offsetWidth; // ری‌استارت انیمیشن
    cartCountEl.classList.add('bump');
  }

  function renderCart() {
    const totalQty = cart.reduce((sum, i) => sum + i.qty, 0);
    cartCountEl.textContent = totalQty;

    cartDrawer.classList.toggle('is-empty', cart.length === 0);

    cartItemsEl.innerHTML = cart.map(item => {
      const product = PRODUCTS.find(p => p.id === item.id);
      return `
        <div class="cart-item">
          <div class="cart-item-media" style="--tag-color:${product.color}">${productVisual(product, 'cart-' + item.id + '-' + item.size)}</div>
          <div class="cart-item-info">
            <h5>${product.name}</h5>
            <div class="cart-item-price price-mono">${formatToman(product.price)} · سایز ${item.size}</div>
            <div class="qty-control">
              <button data-qty-minus="${item.id}-${item.size}" aria-label="کم کردن">−</button>
              <span>${item.qty}</span>
              <button data-qty-plus="${item.id}-${item.size}" aria-label="زیاد کردن">+</button>
              <button class="remove-btn" data-remove="${item.id}-${item.size}">حذف</button>
            </div>
          </div>
        </div>
      `;
    }).join('');

    const total = cart.reduce((sum, item) => {
      const product = PRODUCTS.find(p => p.id === item.id);
      return sum + product.price * item.qty;
    }, 0);
    cartTotalEl.textContent = formatToman(total);
  }

  cartItemsEl.addEventListener('click', (e) => {
    const minus = e.target.closest('[data-qty-minus]');
    const plus = e.target.closest('[data-qty-plus]');
    const remove = e.target.closest('[data-remove]');

    if (minus) { const [id, size] = minus.dataset.qtyMinus.split('-').map(Number); changeQty(id, size, -1); }
    if (plus) { const [id, size] = plus.dataset.qtyPlus.split('-').map(Number); changeQty(id, size, 1); }
    if (remove) { const [id, size] = remove.dataset.remove.split('-').map(Number); removeFromCart(id, size); }
  });

  function openCart() {
    cartDrawer.classList.add('open');
    cartDrawer.setAttribute('aria-hidden', 'false');
    overlay.classList.add('show');
  }
  function closeCart() {
    cartDrawer.classList.remove('open');
    cartDrawer.setAttribute('aria-hidden', 'true');
    if (!quickView.classList.contains('open') && !authModal.classList.contains('open') && !mainNav.classList.contains('open')) {
      overlay.classList.remove('show');
    }
  }

  cartBtn.addEventListener('click', openCart);
  closeCartBtn.addEventListener('click', closeCart);
  cartEmptyBtn.addEventListener('click', closeCart);
  overlay.addEventListener('click', () => { closeCart(); closeQuickView(); closeMobileMenu(); closeAuthModal(); });

  $('#checkoutBtn').addEventListener('click', () => {
    if (cart.length === 0) return;
    showToast('سفارش شما با موفقیت ثبت شد 🎉');
    cart = [];
    renderCart();
    closeCart();
  });

  /* -------------------- 5. نمای سریع (Modal) -------------------- */
  const quickView = $('#quickView');
  const quickViewBox = $('#quickViewBox');
  let selectedSize = SIZES[2];

  function openQuickView(id) {
    const product = PRODUCTS.find(p => p.id === id);
    if (!product) return;
    selectedSize = SIZES[2];

    quickViewBox.innerHTML = `
      <button class="modal-close" id="modalClose" aria-label="بستن">✕</button>
      <div class="modal-media" style="--tag-color:${product.color}">${productVisual(product, 'modal-' + product.id)}</div>
      <div class="modal-info">
        <span class="card-cat">${CATEGORY_LABELS[product.category]}</span>
        <h3>${product.name}</h3>
        <p class="modal-desc">طراحی سبک و تنفس‌پذیر، مناسب استفاده روزانه با دوامی که تا فصل‌ها ادامه دارد.</p>
        <span class="modal-price price-mono">${formatToman(product.price)}</span>
        <div class="size-list" id="sizeList">
          ${SIZES.map(s => `<button data-size="${s}" class="${s === selectedSize ? 'selected' : ''}">${s}</button>`).join('')}
        </div>
        <button class="btn btn-primary btn-block" id="modalAddBtn">افزودن به سبد خرید</button>
      </div>
    `;

    quickView.classList.add('open');
    quickView.setAttribute('aria-hidden', 'false');
    overlay.classList.add('show');

    $('#modalClose', quickViewBox).addEventListener('click', closeQuickView);
    $('#sizeList', quickViewBox).addEventListener('click', (e) => {
      const btn = e.target.closest('button');
      if (!btn) return;
      $$('button', $('#sizeList', quickViewBox)).forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      selectedSize = Number(btn.dataset.size);
    });
    $('#modalAddBtn', quickViewBox).addEventListener('click', () => {
      addToCart(product.id, selectedSize);
      showToast('به سبد خرید اضافه شد ✓');
      closeQuickView();
    });
  }

  function closeQuickView() {
    quickView.classList.remove('open');
    quickView.setAttribute('aria-hidden', 'true');
    if (!cartDrawer.classList.contains('open') && !authModal.classList.contains('open') && !document.getElementById('mainNav').classList.contains('open')) {
      overlay.classList.remove('show');
    }
  }

  /* -------------------- ورود / ثبت‌نام -------------------- */
  const authModal = $('#authModal');
  const authBtn = $('#authBtn');
  const authClose = $('#authClose');
  const authStepPhone = $('#authStepPhone');
  const authStepCode = $('#authStepCode');
  const authPhone = $('#authPhone');
  const authCode = $('#authCode');
  const authMessage = $('#authMessage');
  const authSendBtn = $('#authSendBtn');
  const authVerifyBtn = $('#authVerifyBtn');
  const authBack = $('#authBack');

  function resetAuthForm() {
    authStepPhone.hidden = false;
    authStepCode.hidden = true;
    authPhone.value = '';
    authCode.value = '';
    authMessage.textContent = '';
    authMessage.classList.remove('success');
  }

  function openAuthModal() {
    authModal.classList.add('open');
    authModal.setAttribute('aria-hidden', 'false');
    overlay.classList.add('show');
    setTimeout(() => authPhone.focus(), 300);
  }

  function closeAuthModal() {
    authModal.classList.remove('open');
    authModal.setAttribute('aria-hidden', 'true');
    if (!cartDrawer.classList.contains('open') && !quickView.classList.contains('open') && !mainNav.classList.contains('open')) {
      overlay.classList.remove('show');
    }
    setTimeout(resetAuthForm, 300);
  }

  authBtn.addEventListener('click', openAuthModal);
  authClose.addEventListener('click', closeAuthModal);

  authSendBtn.addEventListener('click', () => {
    const phone = authPhone.value.trim();
    if (phone.length !== 11 || !phone.startsWith('09') || !/^\d+$/.test(phone)) {
      authMessage.classList.remove('success');
      authMessage.textContent = 'لطفاً یک شماره موبایل معتبر ۱۱ رقمی وارد کن.';
      return;
    }
    authStepPhone.hidden = true;
    authStepCode.hidden = false;
    authMessage.classList.add('success');
    authMessage.textContent = `کد تایید به شماره ${phone} پیامک شد (شبیه‌سازی)`;
    setTimeout(() => authCode.focus(), 50);
  });

  authVerifyBtn.addEventListener('click', () => {
    const code = authCode.value.trim();
    if (code.length !== 4 || !/^\d+$/.test(code)) {
      authMessage.classList.remove('success');
      authMessage.textContent = 'کد تایید باید ۴ رقم باشد.';
      return;
    }
    authMessage.classList.add('success');
    authMessage.textContent = 'ورود با موفقیت انجام شد 🎉';
    showToast('خوش اومدی! ورود موفق بود ✓');
    setTimeout(closeAuthModal, 900);
  });

  authBack.addEventListener('click', () => {
    authStepCode.hidden = true;
    authStepPhone.hidden = false;
    authMessage.textContent = '';
    authMessage.classList.remove('success');
    setTimeout(() => authPhone.focus(), 50);
  });

  authPhone.addEventListener('keydown', (e) => { if (e.key === 'Enter') authSendBtn.click(); });
  authCode.addEventListener('keydown', (e) => { if (e.key === 'Enter') authVerifyBtn.click(); });

  /* -------------------- 6. هدر، منوی موبایل، اسکرول -------------------- */
  const siteHeader = $('#siteHeader');
  const menuToggle = $('#menuToggle');
  const mainNav = $('#mainNav');
  const navLinks = $$('[data-nav]');
  const backToTop = $('#backToTop');

  function closeMobileMenu() {
    menuToggle.classList.remove('open');
    menuToggle.setAttribute('aria-expanded', 'false');
    mainNav.classList.remove('open');
    if (!cartDrawer.classList.contains('open') && !quickView.classList.contains('open') && !authModal.classList.contains('open')) {
      overlay.classList.remove('show');
    }
  }

  menuToggle.addEventListener('click', () => {
    const isOpen = mainNav.classList.toggle('open');
    menuToggle.classList.toggle('open', isOpen);
    menuToggle.setAttribute('aria-expanded', String(isOpen));
    overlay.classList.toggle('show', isOpen);
  });

  navLinks.forEach(link => {
    link.addEventListener('click', () => {
      navLinks.forEach(l => l.classList.remove('active'));
      link.classList.add('active');
      closeMobileMenu();
    });
  });

  function handleScroll() {
    const scrolled = window.scrollY > 30;
    siteHeader.classList.toggle('scrolled', scrolled);
    backToTop.classList.toggle('show', window.scrollY > 500);
  }
  window.addEventListener('scroll', handleScroll, { passive: true });

  backToTop.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeCart();
      closeQuickView();
      closeMobileMenu();
      closeSortDropdown();
      closeAuthModal();
    }
  });

  /* -------------------- 7. ریویل + شمارنده آمار -------------------- */
  const revealEls = $$('.reveal');
  const statEls = $$('.stat-num');
  let statsAnimated = false;

  function animateCounters() {
    if (statsAnimated) return;
    statsAnimated = true;
    statEls.forEach(el => {
      const target = Number(el.dataset.count);
      const duration = 1400;
      const start = performance.now();

      function tick(now) {
        const progress = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        el.textContent = Math.floor(eased * target).toLocaleString('fa-IR');
        if (progress < 1) requestAnimationFrame(tick);
        else el.textContent = target.toLocaleString('fa-IR');
      }
      requestAnimationFrame(tick);
    });
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('in-view');
        if (entry.target.classList.contains('stats') || entry.target.querySelector?.('.stat-num')) {
          animateCounters();
        }
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.2 });

  revealEls.forEach(el => observer.observe(el));

  const statsSection = $('.stats');
  if (statsSection) observer.observe(statsSection);

  /* -------------------- 8. خبرنامه + Toast -------------------- */
  const newsletterForm = $('#newsletterForm');
  const newsletterMessage = $('#newsletterMessage');

  newsletterForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const email = $('#newsletterEmail').value.trim();
    if (!email) return;
    newsletterMessage.textContent = `ایمیل ${email} با موفقیت ثبت شد ✓`;
    newsletterMessage.classList.add('show');
    newsletterForm.reset();
    setTimeout(() => newsletterMessage.classList.remove('show'), 4000);
  });

  const toast = $('#toast');
  let toastTimer = null;

  function showToast(message) {
    clearTimeout(toastTimer);
    toast.innerHTML = `<span class="dot"></span> ${message}`;
    toast.classList.add('show');
    toastTimer = setTimeout(() => toast.classList.remove('show'), 2600);
  }

  /* -------------------- شروع -------------------- */
  renderProducts();
  renderCart();
  handleScroll();

})();
